const money=(value:bigint)=>{const sign=value<0n?'-':'';const n=value<0n?-value:value;return sign+(n/1000n).toString().replace(/\B(?=(\d{3})+(?!\d))/gu,',')+'.'+(n%1000n).toString().padStart(3,'0')+' د.أ';};
